  "claims": [
    {
      "claim": "ARISE is an Agentic Rubric-guided Iterative Survey Engine designed for automated generation and continuous refinement of academic survey papers.",
      "source_id": "8ecb8b665692530d",
      "evidence_quote": "To address these limitations, we introduce ARISE, an Agentic Rubric-guided Iterative Survey Engine designed for automated generation and continuous refinement of academic survey papers.",
      "confidence": 1.0
    },
    {
      "claim": "ARISE achieved an average rubric-aligned quality score of 92.48, demonstrating superior performance compared to state-of-the-art automated systems and recent human-written surveys.",
      "source_id": "8ecb8b665692530d",
      "evidence_quote": "Evaluating ARISE against state-of-the-art automated systems and recent human-written surveys, our experimental results demonstrate superior performance, achieving an average rubric-aligned quality score of 92.48.",
      "confidence": 1.0
    },
    {
      "claim": "The review surveys advances in the field of hydrogel matrices from 2016-2026, covering basic principles from single-network to mechanically enhanced double-network systems.",
      "source_id": "0b0ba5b118087dc0",
      "evidence_quote": "This review surveys advances in field over 2016-2026, beginning with basic principles of hydrogel matrices, ranging from simple single-network to mechanically enhanced double-network systems.",
      "confidence": 1.0
    },
    {
      "claim": "The review explores various monitoring mechanisms, explaining how colorimetric agents translate chemical changes into visible color signals.",
      "source_id": "0b0ba5b118087dc0",
      "evidence_quote": "It then explores various monitoring mechanisms, explaining how colorimetric agents, such as halochromic dyes, plasmonic nanoparticles, enzyme-based systems, redox-active metal ions, and biomarker-specific system, translate chemical changes into visible color signals.",
      "confidence": 1.0
    },
    {
      "claim": "This paper systematically reviews LLM-driven phone GUI agents, tracing their evolution from script-based automation to intelligent, adaptive systems.",
      "source_id": "c08c356d65c7b98e",
      "evidence_quote": "This paper systematically reviews LLM-driven phone GUI agents, highlighting their evolution from script-based automation to intelligent, adaptive systems.",
      "confidence": 1.0
    },
    {
      "claim": "LLMs address challenges such as limited generality, high maintenance overhead, and weak intent comprehension through advanced language understanding, multimodal perception, and robust decision-making.",
      "source_id": "c08c356d65c7b98e",
      "evidence_quote": "We first contextualize key challenges, (i) limited generality, (ii) high maintenance overhead, and (iii) weak intent comprehension, and show how LLMs address these issues through advanced language understanding, multimodal perception, and robust decision-making.",
      "confidence": 1.0
    },
    {
      "claim": "A survey systematically deconstructs LLM agent systems using a methodology-centered taxonomy, linking architectural foundations, collaboration mechanisms, and evolutionary pathways.",
      "source_id": "c6ac26dc7a8eac50",
      "evidence_quote": "This survey systematically deconstructs LLM agent systems through a methodology-centered taxonomy, linking architectural foundations, collaboration mechanisms, and evolutionary pathways.",
      "confidence": 1.0
    },
    {
      "claim": "STRUCTSURVEY is a hierarchical multi-agent framework that improves ROUGE-1 recall by +2.9 and ROUGE-2 recall by +1 compared with embedding-only retrieval baselines.",
      "source_id": "87ad4f603172e054",
      "evidence_quote": "Compared with embedding-only retrieval baselines, STRUCTSURVEY improves ROUGE-1 recall by +2.9 and ROUGE-2 recall by +1.",
      "confidence": 1.0
    }
  ]
}

